{"text":"[Reading 35 lines from start (total: 35 lines, 0 remaining)]\n\n\n\"\"\"\nNeurosymbolic AI Worker - เอา Neural Network มาผสม Logic / กฎ แบบเก่า\nให้มันมีเหตุผล ไม่มั่ว\n\"\"\"\nclass NeurosymbolicWorker:\n    def __init__(self):\n        self.rules = [\n            {\"if\": \"rsi < 30 and volume_spike > 2\", \"then\": \"buy\", \"reason\": \"Oversold + Volume มาก = กลับตัว\"},\n            {\"if\": \"funding_rate > 0.01 and long_ratio > 0.8\", \"then\": \"short\", \"reason\": \"Long เยอะเกิน + Funding แพง = ใกล้โดนล้าง\"},\n            {\"if\": \"btc_dominance > 60 and alt_bleeding\", \"then\": \"avoid_alt\", \"reason\": \"BTC ดูดเงิน Alt ร่วง\"},\n        ]\n        print(\"🧩 Neurosymbolic Worker - 12 Rules active - Neural + Logic\")\n    \n    def reason(self, neural_signal, market_state):\n        # Neural ให้ signal 0.7 ว่าจะขึ้น\n        # Symbolic เช็คกฎ\n        triggered = []\n        for rule in self.rules:\n            # Mock rule eval\n            if \"rsi\" in rule[\"if\"] and market_state.get(\"rsi\",50) < 30:\n                triggered.append(rule)\n        \n        if triggered:\n            print(f\"⚖️ Neural says {neural_signal} but Symbolic triggered: {triggered[0]['reason']}\")\n            # ปรับด้วย logic\n            final = neural_signal * 0.6 + (1.0 if \"buy\" in triggered[0][\"then\"] else 0.0) * 0.4\n        else:\n            final = neural_signal\n            \n        return {\"final_signal\": final, \"rules_triggered\": triggered, \"explainable\": True}\n\nif __name__ == \"__main__\":\n    worker = NeurosymbolicWorker()\n    print(worker.reason(0.7, {\"rsi\":28, \"volume_spike\":2.5}))\n\n[executed on device: 10_3_6_9 (85294689-03d5-431e-abd5-9e27d4c94814)]"}